    /** Fixed city-to-canonical-region mapping. */
    private static final Map<String, String> CITY_REGION = Map.of(
        "Sydney", "NSW",
        "Melbourne", "VIC",
        "Brisbane", "QLD");

    /** The locality returned for any city not present in {@link #CITY_REGION}. */
    public static final String UNKNOWN = "UNKNOWN";

    private CityRegion() {
    }

    /**
     * Derive the canonical region for the supplied city.
     *
     * @param city the owner's city (may be {@code null})
     * @return the canonical region string, or {@code "UNKNOWN"} when the city is {@code null}
     *         or not in the table
     */
    public static String localityOf(String city) {
        if (city == null) {
            return UNKNOWN;
        }
        return CITY_REGION.getOrDefault(city, UNKNOWN);
    }
}

